-- Replace the generic one-line News placeholder with useful editorial captions.
-- Guarded deliberately: captions an editor has already customised are never
-- overwritten when this data migration is deployed.
UPDATE "Post"
SET "excerpt" = CASE "slug"
  WHEN 'news-01' THEN 'استفاده از پردازش لبه باعث می‌شود بخشی از تحلیل تصویر نزدیک دوربین انجام شود و فقط داده‌های ضروری به مرکز برسند. برای تیم‌های IT، نتیجه می‌تواند کاهش مصرف پهنای‌باند، پاسخ سریع‌تر به رخدادها و طراحی قابل‌مدیریت‌تر برای سایت‌های دورافتاده باشد؛ البته ظرفیت پردازنده و سیاست نگهداری باید از ابتدا مشخص شود.'
  WHEN 'news-02' THEN 'نسل تازه حافظه‌های سروری با هدف پایین آوردن توان مصرفی در بارهای دائمی معرفی شده است. این تغییر برای دیتاسنترهایی که با هزینه برق و تراکم رک درگیرند مهم است، اما تصمیم خرید باید با بررسی سازگاری پلتفرم، کانال‌های حافظه و تأثیر واقعی آن بر بارهای کاری سازمان انجام شود.'
  WHEN 'news-03' THEN 'رشد ابزارهای متن‌باز مانیتورینگ انتخاب‌های بیشتری در اختیار تیم‌های زیرساخت گذاشته است. ارزش اصلی این ابزارها زمانی دیده می‌شود که هشدارها، داشبوردها و مالکیت سرویس‌ها درست طراحی شوند؛ وگرنه حجم اعلان‌های بی‌اهمیت، همان مسئله‌ای می‌شود که قرار بود با مانیتورینگ حل شود.'
  WHEN 'news-04' THEN 'بکاپ Immutable به یکی از لایه‌های مهم دفاع در برابر باج‌افزار تبدیل شده است، چون نسخه پشتیبان را برای یک بازه مشخص غیرقابل تغییر نگه می‌دارد. سازمان‌ها باید کنار این قابلیت، بازیابی آزمایشی، کنترل دسترسی و محل نگهداری نسخه‌ها را هم بررسی کنند تا در زمان بحران واقعاً قابل استفاده باشند.'
  WHEN 'news-05' THEN 'رقابتی‌تر شدن تجهیزات 10GbE برای کسب‌وکارهای کوچک می‌تواند ارتقای شبکه را از یک پروژه پرهزینه به برنامه‌ای مرحله‌ای تبدیل کند. پیش از خرید، باید ظرفیت سوئیچ، نوع کابل‌کشی، نیاز ذخیره‌سازی و گلوگاه‌های سرور بررسی شود تا افزایش سرعت لینک واقعاً در تجربه کاربران دیده شود.'
  WHEN 'news-06' THEN 'Zero Trust در سازمان‌های متوسط از یک شعار امنیتی به مجموعه‌ای از تصمیم‌های اجرایی نزدیک‌تر شده است. شناسایی هویت، حداقل‌سازی دسترسی، ثبت رخدادها و تفکیک سرویس‌ها باید به‌صورت تدریجی اجرا شوند؛ زیرا پیاده‌سازی یک‌باره بدون شناخت جریان‌های کاری، می‌تواند بهره‌وری تیم‌ها را مختل کند.'
  WHEN 'news-07' THEN 'ابزارهای مدیریت Kubernetes برای دیتاسنترهای کوچک در حال ساده‌تر کردن استقرار، مشاهده‌پذیری و به‌روزرسانی سرویس‌ها هستند. با این حال، استفاده موفق از آن‌ها به استانداردسازی کانفیگ‌ها، پایش منابع و مهارت عملی تیم وابسته است؛ نه فقط اضافه کردن یک لایه جدید به زیرساخت موجود.'
  WHEN 'news-08' THEN 'افزایش تقاضا برای ذخیره‌سازی Object نشان می‌دهد آرشیوهای سازمانی به مقیاس‌پذیری و نگهداری بلندمدت بیشتری نیاز دارند. تیم‌های زیرساخت باید هزینه خروج داده، سیاست نگهداری، رمزنگاری و زمان بازیابی را کنار ظرفیت خام مقایسه کنند تا انتخاب نهایی فقط بر اساس قیمت هر ترابایت نباشد.'
  WHEN 'news-09' THEN 'مستندسازی دقیق زیرساخت می‌تواند زمان تشخیص و رفع قطعی را به‌طور محسوسی کاهش دهد. نقشه ارتباط سرویس‌ها، مالک هر سامانه، مسیرهای بازیابی و تغییرات اخیر باید در دسترس تیم عملیات باشد؛ چون در لحظه رخداد، حافظه افراد جایگزین یک مرجع قابل اعتماد و به‌روز نیست.'
  WHEN 'news-10' THEN 'ورود Wi‑Fi 7 به پروژه‌های چندشعبه‌ای، بحث ظرفیت، تأخیر و مدیریت هم‌زمان کاربران را جدی‌تر کرده است. سازمان‌ها پیش از مهاجرت باید سازگاری کلاینت‌ها، طراحی بک‌هال، توان سوییچ‌های PoE و سیاست رومینگ را بررسی کنند تا نسل جدید شبکه بی‌سیم به نقطه ضعف عملیاتی تبدیل نشود.'
  WHEN 'news-11' THEN 'تمرکز سازندگان UPS بر مانیتورینگ هوشمند باتری به تیم‌ها کمک می‌کند پیش از افت ناگهانی ظرفیت یا خرابی، نشانه‌های خطر را ببینند. داده‌های سلامت باتری زمانی مفید هستند که با برنامه تست دوره‌ای، ثبت بار واقعی و سناریوی خاموشی کنترل‌شده همراه شوند؛ نه فقط یک داشبورد زیبا در اتاق مانیتورینگ.'
  ELSE "excerpt"
END
WHERE "module" = 'news'
  AND "slug" IN (
    'news-01', 'news-02', 'news-03', 'news-04', 'news-05', 'news-06',
    'news-07', 'news-08', 'news-09', 'news-10', 'news-11'
  )
  AND "excerpt" = 'خلاصه خبر و تاثیر آن بر تصمیم‌های تیم‌های IT و زیرساخت در سازمان‌های ایرانی.';
